                    string identity=NavContract.Digest(w=>{w.Write("certified-direct-test");w.Write(provider.Binding);w.Write(input.Entity);w.Write(goal.Position.X);w.Write(goal.Position.Z);});spine=NavRecastSpine.Create(input.Session,dto.GroupId,dto.OrderRevision,dto.CommandSequence,input.Profile.Radius,identity,old.Corridor.TypedRoute.RecastPlan.Spine.MapBinding,recipe.GraphKey,provider.Binding,recipe.Profile.ExactProfileBinding,input.HeldIdentity,input.Geometry.Revision,goal.Position,input.Profile.Radius,trace.Count,trace,r);memberPlan=NavRecastMemberPlan.Create(spine,0,0,0,0,recipe.GraphKey,recipe.Profile.ExactProfileBinding,r);route=NavTypedRoute.CopySubscriptionAndCreateOwned(recipe.Subscription,trace,trace.Sum(l=>l.Cost),r,memberPlan);corridor=NavigationHostCorridor.CreateOwned(request,providerOwner,recipe,route,r);var points=trace.Where(l=>l.Kind==NavTypedLegKind.Surface).Select(l=>l.To.Position).ToArray();answer=NavigationHostAnswer.CreateReady(request,corridor,points,r);global=NavRetainedArray<NavPoint>.Copy(points.Concat(new[]{goal.Position}).ToArray(),r.TryReserve);var owner=NavigationInstalledExecutionOwner.CreateOwned(answer,global,false,r);owners.Add(owner);installed[row]=owner;
