    static NavTypedLeg[] PrimitiveLegs(JToken rows)=>rows.Select(l=>new NavTypedLeg(Location(l["From"]),Location(l["To"]),(double)l["Cost"],Enum.Parse<NavTypedLegKind>((string)l["Kind"]),(string)l["PortalId"])).ToArray();
    static int[] Stops(NavTypedLeg[] legs)=>new[]{0}.Concat(Enumerable.Range(0,legs.Length).Where(i=>legs[i].Kind==NavTypedLegKind.Surface&&(i+1==legs.Length||legs[i+1].Kind!=NavTypedLegKind.Portal)).Select(i=>i+1)).ToArray();
    static void CurrentSession(PlayableAuthorityTick world,NavigationSession s,PlayableProfile profile,JObject raw,string output,bool composed=false)
    {
        // Accepted route primitives enter through the existing registered host
        // factories. The current policy alone creates formation roles. This is
        // a component adapter, not a second native query or ordinary witness.
        var proposals=new Dictionary<string,RecastSpineProposal>();var primitives=new List<NavTypedLeg>();var kernel=new CertifiedRouteKernel();NavigationSession restored=null,cold=null;
        Check(!world.TryAdvance()&&world.Tick==0,"Component expected a normal pending authority grant without World advance");int totalPumps=0;
        void Metrics(string label){var root=s.PinCommittedHostRoot();try{var f=root?.Frontier??default;string json=JsonConvert.SerializeObject(new{Case=label,Tick=world.Tick,s.AppliedResults,s.RejectedResults,Pending=s.Admission.Requests.Count,Registered=s.RegisteredRouteCount,Stage=f.Stage.ToString(),Serial=root?.QuantumSerial,Grant=f.OriginalBudget,Limit=f.SolveWorkLimit,Spent=f.SolveConsumed,Projection=root?.Projection.Count,Completion=root?.Completion.Count,Delivered=root?.Delivered.Count,KernelNativeQueries=kernel.RecastLongQueries,TotalPumps=totalPumps});Console.WriteLine(json);File.AppendAllText(Path.Combine(output,"state-metrics.jsonl"),json+"\n");}finally{root?.Release();}}
        void Assert(string label,bool condition,string text){Metrics(label);Check(condition,text);}
        void Save(string name){using var state=s.CaptureState();File.WriteAllBytes(Path.Combine(output,name+"-nav14.bin"),WorldWire.Pack(w=>WorldWire.Write(w,state)));}
        try{
            foreach(var row in raw["Spines"]){var legs=PrimitiveLegs(row["Legs"]);primitives.AddRange(legs);proposals.Add((string)row["Binding"],new RecastSpineProposal(legs,(string)row["Binding"],(string)row["MapBinding"],(int)row["FanNode"],Stops(legs),Point(row["FanCenter"]),(double)row["FanRadius"]));}
            var build=typeof(CertifiedRouteKernel).GetMethod("BuildScheduled",BindingFlags.Static|BindingFlags.NonPublic);int registered=0;
            while(s.RoutePort.TryObservePhysicalIngress(out var request,out var observed))using(observed){
                var row=raw["Routes"].Single(t=>(int)t["Id"]==request.Entity);var legs=PrimitiveLegs(row["Legs"]);primitives.AddRange(legs);var provider=new PartitionNavigationProvider(profile.AuthoredMap,request.Geometry,request.HeldIdentity);Check(provider.Binding==(string)row["ProviderBinding"],"Current ingress provider differs from actual accepted route");var prepared=(NavScheduledRequest)build.Invoke(null,new object[]{observed.Value,request,provider});
                var points=Stops(legs).Skip(1).Select(i=>new RecastRoutePoint(legs[i-1].To,0)).ToArray();var proposal=new RecastMemberRoute(points,legs,proposals[(string)row["Spine"]],(int)row["Join"],(int)row["Exit"],(int)row["OriginLegs"],(int)row["TerminalLeg"]);
                var source=s.PinCommittedHostRoot();NavigationHostRoot next=null;NavigationRetentionBudget.Scope scope=null;
                try{Check(s.TryOpenPhysicalHostScope(NavigationPreparationKind.RouteAdmission,source?.Epoch??805,observed.Value.PublicationIdentity,out scope),"Current primitive ingress scope refused");var r=scope.OwnedReservation();next=source==null?s.RoutePort.CreatePhysicalHostRoot(r):source.ForkOwned(r);var key=next.RegisterRecast(request,prepared,proposal,NavSolveStatus.Ready,observed.Value.SurfaceProviderId,r);next.SealPrepared();s.RoutePort.PublishRegisteredPhysicalHost(scope,source,next,observed.Value,request,key);registered++;}
                finally{next?.ReleaseStorage();scope?.Discard();source?.Release();}
            }
            Assert("ingress-final-before-assert",registered==50&&s.Requests.Count==0,"Actual fifty ingress incomplete");
            if(composed){ComposedBoundary(world,s,kernel,output,registered);return;}
            kernel.PauseAtPhysicalBoundary=()=>kernel.CapturePumpFrontier().Stage==CertifiedRouteKernel.PumpStage.Solve;kernel.Pump(world.NavigationBinding,4);totalPumps++;var frontier=kernel.CapturePumpFrontier();Assert("pending-quota-before-assert",frontier.OriginalBudget==4&&frontier.SolveWorkLimit==4096&&frontier.SolveConsumed==0,"Current actual pending quota boundary changed");
            using(var state=s.CaptureState()){long captureTick=world.Tick;var bytes=WorldWire.Pack(w=>WorldWire.Write(w,state));File.WriteAllBytes(Path.Combine(output,"quota-collecting-nav14.bin"),bytes);using var saved=WorldWire.Unpack(bytes,WorldWire.ReadNavigationSessionState);cold=FormationPreflight.FromSnapshot(saved,profile);using var current=cold.CaptureState();Console.WriteLine(JsonConvert.SerializeObject(new{Case="pending-restore-ticks",CaptureTick=captureTick,AfterRestoreTick=world.Tick}));Assert("pending-roundtrip-before-assert",captureTick==world.Tick&&bytes.SequenceEqual(WorldWire.Pack(w=>WorldWire.Write(w,current))),"Current PendingCollecting actual quota roundtrip changed");}
            kernel.PauseAtPhysicalBoundary=null;
            while(totalPumps<300&&world.Tick<256&&s.AppliedResults<50&&s.RejectedResults==0&&kernel.RecastLongQueries==0){world.TryAdvance();kernel.Pump(world.NavigationBinding,4);totalPumps++;s.ApplyResults();Metrics("normal-authority-progression");}
            Metrics("ready-final-before-capture");Save("ready-final");Assert("ready-final-before-assert",s.AppliedResults==50&&s.RejectedResults==0&&s.Admission.Requests.Count==0&&kernel.RecastLongQueries==0&&world.Tick<=256&&totalPumps<=300,"Current accepted primitive installation incomplete, rejected, queried native or exceeded bounds");
            void SessionRoundTrip(string name){long captureTick=world.Tick;Metrics(name+"-before-capture");using var state=s.CaptureState();var bytes=WorldWire.Pack(w=>WorldWire.Write(w,state));File.WriteAllBytes(Path.Combine(output,name+"-nav14.bin"),bytes);using var saved=WorldWire.Unpack(bytes,WorldWire.ReadNavigationSessionState);restored=FormationPreflight.FromSnapshot(saved,profile);using var current=restored.CaptureState();Console.WriteLine(JsonConvert.SerializeObject(new{Case=name+"-restore-ticks",CaptureTick=captureTick,AfterRestoreTick=world.Tick}));Assert(name+"-roundtrip-before-assert",captureTick==world.Tick&&bytes.SequenceEqual(WorldWire.Pack(w=>WorldWire.Write(w,current))),"Current "+name+" full Nav14 recapture changed");Assert(name+"-binding-before-assert",s.GroupFor(3).IssuedTick==restored.GroupFor(3).IssuedTick&&s.GroupFor(3).FormationSeal==restored.GroupFor(3).FormationSeal,"Current issuance/mapping changed");}
            SessionRoundTrip("Ready-Collecting");restored.ReleaseCommittedHostRoot();restored.DestroyNavigationAuthority();restored=null;
            var before=s.Crowd.Units.ToDictionary(a=>a.Id,a=>new{a.Position,a.noProgressTicks,a.blockedSeconds});s.Step(1d/30);var group=s.GroupFor(3);Save("feeding-before-assert");Assert("feeding-before-assert",group.FormationPlan?.Phase==RecastFormationPhase.Feeding&&group.FormationPlan.LaneCount==3,"Current physical consumer did not enter Feeding");
            foreach(var e in group.FormationPlan.Entries)if(e.Stage==RecastPassageStage.Staging){s.Crowd.TryGet(e.Entity,out var actor);Assert("staging-counters-before-assert",actor.noProgressTicks==before[e.Entity].noProgressTicks&&actor.blockedSeconds==before[e.Entity].blockedSeconds,"Voluntary staging wait counted as physical block");}
            SessionRoundTrip("Feeding-wait");s.Step(1d/30);restored.Step(1d/30);foreach(var actor in s.Crowd.Units){restored.Crowd.TryGet(actor.Id,out var other);Assert("derived-continuation-before-assert",actor.Position.Equals(other.Position)&&actor.Heading==other.Heading&&actor.Moving==other.Moving,"Derived guide rebuild changed continuation");}
            Console.WriteLine(JsonConvert.SerializeObject(new{Case="current-full-Nav14-session",Result="PASS",Registered=registered,Applied=s.AppliedResults,NativeQueries=kernel.RecastLongQueries,PendingOriginalBudget=frontier.OriginalBudget,PendingSolveLimit=frontier.SolveWorkLimit,PendingSpent=frontier.SolveConsumed,Ready=true,Feeding=true,DerivedGuideContinuation=true,StagingVoluntaryWait=true}));
        }finally{Metrics("finally-before-cleanup");try{Save("final-preserved");}catch(Exception error){Console.WriteLine(JsonConvert.SerializeObject(new{Case="final-capture-error",Error=error.ToString()}));}kernel.Clear();foreach(var session in new[]{restored,cold})if(session!=null){session.ReleaseCommittedHostRoot();session.DestroyNavigationAuthority();Check(session.PhysicalHostBudget.PhysicalBytes==0&&session.PhysicalHostBudget.HeldBytes==0&&session.PhysicalHostBudget.ActiveScopes==0,"Current-state restored session leaked");}foreach(var leg in primitives)leg.ReleaseStorage();}
    }

    static void ComposedBoundary(PlayableAuthorityTick world,NavigationSession s,CertifiedRouteKernel kernel,string output,int registered)
    {
        int pumps=0;bool saved49=false,finalComposed=false;string stop="bounds";
        object Probe(object owner,string name){if(owner==null)return "UNKNOWN:null-owner";var property=owner.GetType().GetProperty(name,Hidden);if(property!=null)return property.GetValue(owner);var field=owner.GetType().GetField(name,Hidden);return field==null?"UNKNOWN:missing":field.GetValue(owner);}
        string[] names={"LastNavigationStepPath","OwnedResultBatchPublications","LastResultBatchFailure","LastResultBatchStage","LastResultBatchSourceReason","LastResultBatchDetail","OwnedMovementPublications","OwnedMovementRefusals","LastOwnedMovementNullReason","LastOwnedMovementNullDetail","LastOwnedMovementNullActor","LastOwnedMovementNullGroup","LastOwnedMovementRefusal","LastOwnedMovementRefusalMessage","LastTrafficDispatchStage","LastAnswerNamesFailure"};
        void Save(string name){using var state=s.CaptureState();File.WriteAllBytes(Path.Combine(output,name+"-nav14.bin"),WorldWire.Pack(w=>WorldWire.Write(w,state)));}
        void Metrics(string label){var root=s.PinCommittedHostRoot();try{
            var bank=Probe(s,"creditBank") as NavPagedList<long>;var credits=new Dictionary<string,object>();foreach(string name in new[]{"Watermark","Cap","Count","Accepted","Promoted","Discarded","SaturationDrops"}){var f=typeof(NavigationAccruedCredits).GetField(name,BindingFlags.Static|BindingFlags.NonPublic|BindingFlags.Public);credits[name]=bank==null||f==null?"UNKNOWN":bank[(int)f.GetRawConstantValue()];}
            var g=s.GroupFor(3);var plan=g?.FormationPlan;var f0=root?.Frontier??default;var bodies=s.Crowd.Units.Select(a=>new{a.Id,a.InstalledRequest,a.Moving,Outcome=a.Outcome.ToString(),a.Position}).ToArray();
            var json=JsonConvert.SerializeObject(new{Case=label,Source=Environment.GetEnvironmentVariable("SPACEWARS_QA_SOURCE"),Tick=world.Tick,TotalPumps=pumps,s.AppliedResults,s.RejectedResults,Pending=s.Admission.Requests.Count,Registered=s.RegisteredRouteCount,HostRows=root==null?(object)"UNKNOWN":root.Rows.Count,Projection=root==null?(object)"UNKNOWN":root.Projection.Count,Completion=root==null?(object)"UNKNOWN":root.Completion.Count,Delivered=root==null?(object)"UNKNOWN":root.Delivered.Count,Stage=root==null?"UNKNOWN":f0.Stage.ToString(),Serial=Probe(root,"QuantumSerial"),QuantumRunnable=Probe(root,"QuantumRunnable"),Grant=f0.OriginalBudget,Limit=f0.SolveWorkLimit,Spent=f0.SolveConsumed,Credits=credits,Diagnostics=names.ToDictionary(n=>n,n=>Probe(s,n)),Formation=plan==null?null:new{Phase=plan.Phase.ToString(),Rows=plan.Entries.Count,plan.LaneCount,plan.Seal},Bodies=bodies,NativeQueries=kernel.RecastLongQueries});
            Console.WriteLine(json);File.AppendAllText(Path.Combine(output,"composed-metrics.jsonl"),json+"\n");
        }finally{root?.Release();}}
        try{
            Metrics("composed-before-first-normal-step");
            while(pumps<300&&world.Tick<256&&s.AppliedResults<50&&s.RejectedResults==0&&kernel.RecastLongQueries==0){
                if(!saved49&&s.Crowd.Units.Count(a=>a.InstalledRequest>0)==49){Metrics("first49-before-next-step");Save("first49-before-next-step");saved49=true;}
                long refusals=s.OwnedMovementRefusals;long priorApplied=s.AppliedResults;int priorBatches=s.OwnedResultBatchPublications;var priorPhase=s.GroupFor(3)?.FormationPlan?.Phase;
                world.TryAdvance(); // Domain.Navigation.Step is the sole result/motion consumer.
                Metrics("after-normal-world-TryAdvance");
                if(priorApplied<50&&s.AppliedResults==50){var afterPhase=s.GroupFor(3)?.FormationPlan?.Phase;finalComposed=s.OwnedResultBatchPublications>priorBatches&&s.LastNavigationStepPath==9&&priorPhase==RecastFormationPhase.Collecting&&afterPhase==RecastFormationPhase.Feeding;string transition=JsonConvert.SerializeObject(new{Case="transition-into-Applied50",Tick=world.Tick,PriorApplied=priorApplied,AfterApplied=s.AppliedResults,PriorBatchCount=priorBatches,AfterBatchCount=s.OwnedResultBatchPublications,s.LastNavigationStepPath,PhaseBefore=priorPhase?.ToString(),PhaseAfter=afterPhase?.ToString(),QualifiedComposed=finalComposed});Console.WriteLine(transition);File.WriteAllText(Path.Combine(output,"final-transition.json"),transition+"\n");}
                if(s.LastResultBatchFailure!=null||s.OwnedMovementRefusals>refusals){stop="first-existing-refusal";break;}
                kernel.Pump(world.NavigationBinding,4);pumps++;Metrics("after-normal-kernel-pump");
            }
            Metrics("composed-final-before-assert");Save("composed-final-before-assert");
            var group=s.GroupFor(3);var plan=group?.FormationPlan;
            Check(s.AppliedResults==50&&s.RejectedResults==0&&s.Admission.Requests.Count==0&&kernel.RecastLongQueries==0&&world.Tick<=256&&pumps<=300,"Composed current installation incomplete/rejected/queried/exceeded bounds: "+stop);
            Check(plan?.Phase==RecastFormationPhase.Feeding&&plan.Entries.Count==50&&plan.Entries.Select(e=>e.EntryOrdinal).Distinct().Count()==50,"Composed current final Ready did not freeze50 Feeding mapping");
            Check(finalComposed,"Final Applied50 transition did not prove owned composed path9 plus batch increase and Collecting→Feeding");
            Console.WriteLine(JsonConvert.SerializeObject(new{Case="current-composed-final-Ready",Result="PASS",Tick=world.Tick,Pumps=pumps,registered,s.AppliedResults,s.RejectedResults,Feeding=true,FrozenRows=plan.Entries.Count,NativeQueries=kernel.RecastLongQueries,Meaning="Component only; no async or arrival acceptance"}));
        }finally{Metrics("composed-finally-before-cleanup");try{Save("composed-final-preserved");}catch(Exception error){Console.WriteLine(JsonConvert.SerializeObject(new{Case="composed-final-capture-error",Error=error.ToString()}));}}
    }

